import { useState } from "react";
import { Button, PageHeader, RecordList, StatusPill, Typography } from "@autograph/components";
import { RecordDetailPanel, RecordListDetailLayout } from "@autograph/compositions";

const people = [
  { id: "casey", name: "Casey Morgan", from: "Data Platform", to: "Engineering Platform", kind: "Team change" },
  { id: "riley", name: "Riley Park", from: "Engineering Platform", to: "Engineering Platform", kind: "No team change" },
] as const;

type Decision = "undecided" | "recommend" | "revise";

export default function ReorganizationReview() {
  const [selectedId, setSelectedId] = useState("casey");
  const [established, setEstablished] = useState(false);
  const [decision, setDecision] = useState<Decision>("undecided");
  const selected = people.find((person) => person.id === selectedId) ?? people[0];
  const savings = 3180000 - 3040000;

  return (
    <main className="min-h-screen bg-[var(--color-bg-page)] p-[var(--space-6)] text-[var(--color-text-primary)]">
      <div className="mx-auto grid max-w-[1280px] gap-[var(--space-6)]">
        <PageHeader
          title="Platform consolidation review"
          subtitle="SCN-17 · Effective January 1, 2027 · Draft simulation"
          actions={<StatusPill label="Draft" tone="warning" detail="Not applied" />}
        />

        <RecordDetailPanel
          title="Review decision"
          subtitle="Compare the current organization with the proposed design before recording a recommendation. No organizational records will change."
          status={{
            label: decision === "undecided" ? "Awaiting review" : decision === "recommend" ? "Recommendation recorded" : "Revision requested",
            tone: decision === "undecided" ? "neutral" : decision === "recommend" ? "success" : "warning",
            detail: "Simulation only",
          }}
          labelEmphasis="primary"
          actionsPlacement="header"
          actions={[
            { id: "revise", label: "Request revision", intent: "secondary" },
            { id: "recommend", label: "Recommend proposal", intent: "primary-strong" },
            ...(decision !== "undecided" ? [{ id: "reset", label: "Clear decision", intent: "ghost" as const }] : []),
          ]}
          onAction={(action) => {
            if (action === "recommend") setDecision("recommend");
            if (action === "revise") setDecision("revise");
            if (action === "reset") setDecision("undecided");
          }}
          sections={[
            {
              id: "decision-evidence",
              title: "Decision evidence",
              collapsible: false,
              items: [
                {
                  type: "note",
                  id: "simulation-warning",
                  title: "Draft proposal",
                  body: "All proposed reporting and team changes are hypothetical. Recording a recommendation does not apply the reorganization or notify anyone.",
                  tone: "warning",
                },
                {
                  type: "table",
                  id: "comparison",
                  ariaLabel: "Current and proposed organization comparison",
                  density: "regular",
                  columns: [
                    { id: "measure", label: "Measure" },
                    { id: "current", label: "Current organization" },
                    { id: "proposed", label: "Proposed organization" },
                    { id: "tradeoff", label: "Material change" },
                  ],
                  rows: [
                    { measure: "Managers", current: 6, proposed: 5, tradeoff: "1 fewer manager" },
                    { measure: "Layers", current: 4, proposed: 3, tradeoff: "1 fewer layer" },
                    { measure: "Annual cost", current: "$3,180,000", proposed: "$3,040,000", tradeoff: `$${savings.toLocaleString()} lower annually` },
                    { measure: "Affected people", current: "—", proposed: 18, tradeoff: "Requires transition review" },
                  ],
                },
              ],
            },
          ]}
        />

        <section aria-labelledby="affected-heading" className="grid gap-[var(--space-3)]">
          <div>
            <Typography as="h2" variant="section-title" className="m-0" id="affected-heading">Affected people</Typography>
            <Typography tone="secondary" className="mt-[var(--space-1)] mb-0">2 named examples shown from 18 affected people. Select a person to inspect the simulated transition.</Typography>
          </div>
          <RecordListDetailLayout
            hasSelection={Boolean(selected)}
            selectedId={selectedId}
            showDetailOnConstrained={established}
            onBack={() => setEstablished(false)}
            backLabel="Back to affected people"
            list={({ isDetailVisible }) => (
              <RecordList
                ariaLabel="Affected people in the draft proposal"
                heading="Named changes"
                summary="2 of 18 shown"
                description="Only fields needed to identify a transition appear here; supporting detail stays in the review panel."
                selectedId={isDetailVisible ? selectedId : undefined}
                onSelect={(id) => { setSelectedId(id); setEstablished(true); }}
                items={people.map((person) => ({
                  id: person.id,
                  primary: person.name,
                  secondary: person.from,
                  trailing: <StatusPill label={person.kind} tone={person.id === "casey" ? "info" : "neutral"} size="xs" />,
                }))}
              />
            )}
            detail={
              <RecordDetailPanel
                title={selected.name}
                subtitle="Proposed transition · simulation only"
                status={{ label: selected.kind, tone: selected.id === "casey" ? "info" : "neutral" }}
                labelEmphasis="primary"
                sections={[
                  {
                    id: "transition",
                    title: "Current and proposed assignment",
                    collapsible: false,
                    items: [
                      { type: "field", id: "current-team", label: "Current team", value: selected.from },
                      { type: "field", id: "proposed-team", label: "Proposed team", value: selected.to },
                      {
                        type: "note",
                        id: "interpretation",
                        title: selected.id === "casey" ? "Material move" : "No team reassignment",
                        body: selected.id === "casey" ? "Casey would move from Data Platform to Engineering Platform if the proposal were later approved and applied." : "Riley remains in Engineering Platform. They may still be affected by reporting-line or operating-model changes not represented in this fixture.",
                        tone: selected.id === "casey" ? "info" : "neutral",
                      },
                    ],
                  },
                ]}
              />
            }
          />
        </section>
      </div>
    </main>
  );
}
